import { ref } from 'vue'

// 전역 상태 (Singleton)
const isLoading = ref(false)
const loadingTxt = ref('')
const hasTxt = ref(false)
const timeoutMs = 600000;

export const useGlobalLoading = () => {
    const startLoading = (txt = '') => {
        if (txt) {
            loadingTxt.value = txt
            hasTxt.value = true
        } else {
            loadingTxt.value = ''
            hasTxt.value = false
        }

        isLoading.value = true
    }

    const stopLoading = () => {
        isLoading.value = false
    }

    return {
        isLoading,
        loadingTxt,
        hasTxt,
        timeoutMs,
        startLoading,
        stopLoading,
    }
